\item Schorer, ``The phylogenetic position of the Dura Language of Nepal'' (University of Bern repository). \url{https://boris.unibe.ch/73504/}
\item Dura entry in the Chan numerals database. \url{https://lingweb.eva.mpg.de/channumerals/Dura.htm}
\end{itemize}
